// Extracts technique text from the gmbinder source into typed data files.
//
//   node scripts/extract-techniques.mjs
//
// Reads reference/atla-homebrew-gmbinder.txt (git-ignored, local only) and writes
// src/data/techniques/*.generated.ts. The generated files ARE committed, so the app
// builds without the source. Mechanics (damage, saves) are authored by hand in
// src/data/techniques/mechanics.ts and never overwritten by this script.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
// Obvious typos in the source that would otherwise leak into names and ids.
const TYPOS = [
    ['**Arche**r:', '**Archer**:'],
    ['Motiavtional', 'Motivational'],
    ['Radşus', 'Radius'],
    ['minutees', 'minutes'],
]

let text = readFileSync(join(root, 'reference', 'atla-homebrew-gmbinder.txt'), 'utf8').replace(/\r\n/g, '\n')
for (const [wrong, right] of TYPOS) text = text.split(wrong).join(right)
const source = text.split('\n')
const outDir = join(root, 'src', 'data', 'techniques')
mkdirSync(outDir, { recursive: true })

const find = (predicate, from = 0) => {
    for (let i = from; i < source.length; i += 1) if (predicate(source[i])) return i
    throw new Error('marker not found')
}

const slug = (text) =>
    text
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')

/** Drop layout noise; keep the words. */
function cleanBody(lines) {
    return lines
        .filter((line) => !/^\\(pagebreakNum|columnbreak)/.test(line.trim()))
        .filter((line) => !/^<img|^\/>|^\s*style=|^\s*src=/.test(line.trim()))
        .filter((line) => !/^<div|^<\/div|^<br\/>\s*$/.test(line.trim()))
        .map((line) => line.replace(/<br\/>/g, ' ').replace(/\s+$/g, '').replace(/^\s+(?=[-*])/, ''))
        .filter((line) => line.trim() !== '')
        .join('\n')
        .trim()
}

/**
 * `wanted` maps the italic label under a technique's name to what it becomes:
 * { element } for the base element, or { element, discipline } for a sub-bending that a subclass unlocks.
 * Labels not listed are skipped (Lightningbending and the Fire-list Healing entry: see docs/RULES_QUESTIONS.md).
 */
function parseSpellSection(start, end, prefix, wanted) {
    const techniques = []
    let i = start
    while (i < end) {
        if (!source[i].startsWith('#### ')) {
            i += 1
            continue
        }
        const heading = source[i].replace('#### ', '').trim()
        const rare = heading.endsWith('*')
        const name = heading.replace(/\*+$/, '').trim()
        let j = i + 1
        const elementLine = (source[j] ?? '').replace(/\*/g, '').trim()
        const stats = {}
        let prerequisite
        j += 1
        if (source[j]?.startsWith('___')) j += 1
        while (j < end && !source[j].startsWith('___')) {
            const line = source[j].trim()
            const field = line.match(/^- \*\*(Casting Time|Range|Components|Duration):\*\*\s*(.*)$/)
            const ranged = line.match(/^- \*\*(Ranged.*?)\*\*\s*(.*)$/)
            const pre = line.match(/^- \*?\*?Prerequisite:?\*?\*?:?\s*\*?(.*?)\*?$/)
            if (field) stats[field[1]] = field[2].trim()
            else if (ranged) stats.Range = `${ranged[1]} ${ranged[2]}`.trim()
            else if (pre) prerequisite = pre[1].replace(/\*/g, '').trim()
            j += 1
        }
        j += 1 // closing ___
        const bodyStart = j
        while (j < end && !source[j].startsWith('#### ') && !/^<h[234] id=/.test(source[j])) j += 1
        const body = cleanBody(source.slice(bodyStart, j))

        const kind = wanted[elementLine]
        if (kind) {
            const duration = stats.Duration ?? ''
            techniques.push({
                id: `${prefix}-${slug(name)}`,
                name,
                element: kind.element,
                ...(kind.discipline ? { discipline: kind.discipline } : {}),
                rare,
                ...(prerequisite ? { prerequisite } : {}),
                castingTime: stats['Casting Time'] ?? '',
                range: stats.Range ?? '',
                components: stats.Components ?? '',
                duration,
                concentration: duration.startsWith('Concentration'),
                description: body,
            })
        }
        i = j
    }
    return techniques
}

const literal = (value) => JSON.stringify(value, null, 4)

function write(fileName, exportName, description, items) {
    const text = `// GENERATED by scripts/extract-techniques.mjs from the gmbinder source. Do not edit by hand.
// ${description}
import type { Technique } from '../../types/schema'

export const ${exportName}: Technique[] = ${literal(items)}
`
    writeFileSync(join(outDir, fileName), text)
    console.log(`${fileName}: ${items.length} techniques`)
}

// Universal techniques
const universalStart = find((l) => l.includes('id="UT"'))
const universalEnd = find((l) => l.includes('id="WBT"'), universalStart)
write(
    'universal.generated.ts',
    'universalTechniques',
    'Universal techniques (any class).',
    parseSpellSection(universalStart, universalEnd, 'universal', { Universal: { element: 'Universal' } }),
)

// Earthbending techniques (Metalbending and Lavabending belong to Traditions and are skipped for now)
const earthStart = find((l) => l.includes('Earthbending Techniques</div>'))
const earthEnd = find((l) => l.includes('Firebending Techniques</div>'), earthStart)
write(
    'earth.generated.ts',
    'earthTechniques',
    'Earthbending techniques. Metalbending and Lavabending are not included yet.',
    parseSpellSection(earthStart, earthEnd, 'earth', { Earthbending: { element: 'Earth' } }),
)

// Waterbending: the base list, its Healing techniques, and Bloodbending (unlocked by its path).
const waterStart = find((l) => l.includes('Waterbending Techniques</div>'))
write(
    'water.generated.ts',
    'waterTechniques',
    'Waterbending techniques, including Healing and Bloodbending (tagged with a discipline).',
    parseSpellSection(waterStart, earthStart, 'water', {
        Waterbending: { element: 'Water' },
        // Healing techniques sit in the Waterbending list and nothing restricts them (docs/RULES_QUESTIONS.md L5).
        Healing: { element: 'Water' },
        Bloodbending: { element: 'Water', discipline: 'Bloodbending' },
    }),
)

// Firebending: the base list, Combustionbending (a Principle) and Lightningbending (a feat).
const fireStart = find((l) => l.includes('Firebending Techniques</div>'))
const airStart = find((l) => l.includes('Airbending Techniques</div>'), fireStart)
write(
    'fire.generated.ts',
    'fireTechniques',
    'Firebending techniques, including Combustionbending and Lightningbending (tagged with a discipline).',
    parseSpellSection(fireStart, airStart, 'fire', {
        Firebending: { element: 'Fire' },
        Combustionbending: { element: 'Fire', discipline: 'Combustionbending' },
        // Unlocked by the Lightning Generation feat (docs/RULES_QUESTIONS.md L7).
        Lightningbending: { element: 'Fire', discipline: 'Lightningbending' },
    }),
)

const airEnd = find((l) => l.includes('id="items"'), airStart)
write('air.generated.ts', 'airTechniques', 'Airbending techniques.', parseSpellSection(airStart, airEnd, 'air', { Airbending: { element: 'Air' } }))

// Weaponsmaster fighting techniques: Basic, Trained, Mastered lists share names.
function parseFighting(start, end, levelPrefix) {
    const entries = new Map()
    let current = null

    const startPattern = new RegExp(
        `^(?:<br/>\\s*)*\\*{0,2}(?:${levelPrefix} )?([A-Za-z][A-Za-z -]{2,32}?)\\*{0,2}\\s*(\\((?:Requires Shield|Thrown Weapons Only)\\))?\\*{0,2}\\s*:\\*{0,2}\\s*(.*)$`,
    )

    for (let i = start; i < end; i += 1) {
        const line = source[i].trim().replace(/^<br\/>\s*/, '')
        if (line === '' || /^\\(pagebreakNum|columnbreak)/.test(line) || /^<img|^style=|^\/>|^<h4|^<br\/>$/.test(line)) continue

        const match = line.match(startPattern)
        const looksLikeEntry = match && !/^(For Arms|For Legs)/.test(line)
        if (looksLikeEntry) {
            const raw = match[1].replace(/\*/g, '').trim()
            const name = raw.replace(/^Arche$/, 'Archer').replace(/^Chi-Blocker$/, 'Chi Blocker')
            current = { name, note: match[2] ?? '', text: [match[3].replace(/<br\/>/g, ' ').trim()] }
            entries.set(name, current)
        } else if (current) {
            current.text.push(line.replace(/<br\/>/g, ' ').trim())
        }
    }
    return entries
}

const basicStart = find((l) => l.includes('id="BFT"'))
const trainedStart = find((l) => l.includes('id="TFT"'), basicStart)
const masteredStart = find((l) => l.includes('id="MFT"'), trainedStart)
const fightingEnd = find((l) => l.includes('id="BT"'), masteredStart)

const basic = parseFighting(basicStart, trainedStart, '')
const trained = parseFighting(trainedStart, masteredStart, 'Trained')
const mastered = parseFighting(masteredStart, fightingEnd, 'Mastered')

const fighting = [...basic.values()].map((entry) => {
    const join = (map) => map.get(entry.name)?.text.filter(Boolean).join('\n') ?? ''
    return {
        id: `fighting-${slug(entry.name)}`,
        name: entry.name,
        element: 'Fighting',
        rare: false,
        castingTime: '',
        range: '',
        components: '',
        duration: '',
        concentration: false,
        ...(entry.note ? { prerequisite: entry.note.replace(/[()]/g, '') } : {}),
        description: join(basic),
        levelText: { Practiced: join(basic), Trained: join(trained), Mastered: join(mastered) },
    }
})

write(
    'fighting.generated.ts',
    'fightingTechniques',
    'Weaponsmaster Fighting Techniques (Basic = Practiced).',
    fighting,
)
